begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000201','calendar-a@example.invalid'),('00000000-0000-4000-8000-000000000202','calendar-b@example.invalid'),('00000000-0000-4000-8000-000000000203','calendar-c@example.invalid');
insert into public.households(id,name) values ('00000100-0000-4000-8000-000000000201','Our calendar'),('00000100-0000-4000-8000-000000000202','Other calendar');
insert into public.household_members(household_id,user_id,display_name) values ('00000100-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000201','A'),('00000100-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000202','B'),('00000100-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000203','C');
insert into public.calendar_connections(id,household_id,connected_by,encrypted_credentials,selected_calendar_url,read_only) values ('00000200-0000-4000-8000-000000000201','00000100-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000201','v1.encrypted-fixture-credentials','https://p12-caldav.icloud.com/our-calendar/',false),('00000200-0000-4000-8000-000000000202','00000100-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000203','v1.encrypted-fixture-credentials','https://p12-caldav.icloud.com/other-calendar/',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000201',true);
select is((select count(*) from public.calendar_connections),1::bigint,'connections are tenant scoped');
select is_empty($$update public.calendar_connections set calendar_name='Nope' where id='00000200-0000-4000-8000-000000000202' returning id$$,'foreign connection cannot be edited');
select throws_ok($$select public.claim_calendar_sync('00000200-0000-4000-8000-000000000202')$$,'42501',null,'foreign lease denied');
select throws_ok($$select public.release_calendar_sync('00000200-0000-4000-8000-000000000201',null)$$,'55P03',null,'null token cannot impersonate an unclaimed lease');
select throws_ok($$update public.calendar_connections set sync_lock_until=now()+interval '1 day'$$,'42501',null,'clients cannot extend sync leases directly');
select throws_ok($$insert into public.calendar_connections(household_id,connected_by,encrypted_credentials) values ('00000100-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000201','v1.encrypted-fixture-credentials')$$,'42501',null,'foreign connection insertion denied');
select throws_ok($$delete from public.calendar_connections where id='00000200-0000-4000-8000-000000000201'$$,'42501',null,'direct connection deletion cannot bypass lease guard');
select throws_ok($$insert into public.calendar_connections(household_id,connected_by,encrypted_credentials,sync_lock,sync_lock_until) values ('00000100-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000201','v1.encrypted-fixture-credentials','00000000-0000-4000-8000-000000000299',now()+interval '1 day')$$,'42501',null,'connection insert cannot inject a lease');
select set_config('test.calendar_token',public.claim_calendar_sync('00000200-0000-4000-8000-000000000201')::text,true);
select throws_ok($$select public.claim_calendar_sync('00000200-0000-4000-8000-000000000201')$$,'55P03',null,'concurrent sync cannot claim live lease');
select throws_ok($$select public.disconnect_calendar('00000200-0000-4000-8000-000000000201')$$,'55P03',null,'disconnect cannot race active sync');
select throws_ok($$update public.calendar_connections set encrypted_credentials='v1.new-encrypted-fixture-credentials'$$,'55P03',null,'credentials cannot change during sync');
select throws_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000299','[]')$$,'55P03',null,'stale lease token cannot reconcile');
select lives_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,'[{"uid":"shared-event@example","href":"https://p12-caldav.icloud.com/our-calendar/event.ics","etag":"v1","ical":"original-calendar-data","title":"Dinner","startsAt":"2026-10-01T16:00:00Z","endsAt":"2026-10-01T17:00:00Z","timeZone":"Europe/Zurich","allDay":false,"location":"Home","notes":"","recurrenceRule":null,"cancelled":false}]')$$,'complete remote snapshot imported');
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'synced','imported event is synced');
select set_config('test.calendar_event',(select id::text from public.calendar_events where ical_uid='shared-event@example'),true);
select throws_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,null)$$,'P0001','invalid calendar snapshot','null snapshot rejected');
select throws_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,'[{"uid":12}]')$$,'P0001','invalid calendar snapshot entry','malformed snapshot rejected');
select throws_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,(select jsonb_agg(item) from (select jsonb_build_object('uid','same','href','same','etag','e','ical','data','title','title','startsAt','2026-01-01','endsAt','2026-01-02','timeZone','UTC','location','','notes','','allDay',false,'cancelled',false) item from generate_series(1,2)) entries))$$,'P0001','duplicate calendar snapshot entry','duplicate snapshot identity rejected');
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'synced','invalid snapshots preserve existing events');
update public.calendar_events set title='Booking edited dinner' where ical_uid='shared-event@example';
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'pending','linked booking edit enters sync outbox');
select is((select ical_data from public.calendar_events where ical_uid='shared-event@example'),null::text,'stale canonical calendar data is invalidated');
select is((select ical_edit_base from public.calendar_events where ical_uid='shared-event@example'),'original-calendar-data','regeneration retains prior calendar components');
select throws_ok($$update public.calendar_events set sync_state='synced' where ical_uid='shared-event@example'$$,'P0001','only sync can acknowledge pending calendar edits','client cannot silently discard pending synchronization');
update public.calendar_events set title='Local dinner',ical_data='local-calendar-data',sync_state='pending' where ical_uid='shared-event@example';
select lives_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,'[{"uid":"shared-event@example","href":"https://p12-caldav.icloud.com/our-calendar/event.ics","etag":"v2","ical":"remote-calendar-data","title":"Apple dinner","startsAt":"2026-10-01T18:00:00Z","endsAt":"2026-10-01T19:00:00Z","timeZone":"Europe/Zurich","allDay":false,"location":"Restaurant","notes":"","recurrenceRule":null,"cancelled":false}]')$$,'concurrent edits reconcile as a conflict');
select is((select title from public.calendar_events where ical_uid='shared-event@example'),'Local dinner','remote edit does not overwrite pending local title');
select is((select remote_conflict_ical from public.calendar_events where ical_uid='shared-event@example'),'remote-calendar-data','remote version remains available');
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'conflict','both versions require explicit resolution');
update public.calendar_events set sync_state='pending',ical_data='newer-local-edit' where ical_uid='shared-event@example';
select lives_ok($$select public.record_calendar_push('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,current_setting('test.calendar_event')::uuid,'local-calendar-data',false,'https://p12-caldav.icloud.com/our-calendar/event.ics','v3')$$,'push acknowledgement tolerates a newer local edit');
select is((select ical_data from public.calendar_events where ical_uid='shared-event@example'),'newer-local-edit','push acknowledgement preserves newer edit');
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'pending','newer edit remains queued');
select lives_ok($$select public.reconcile_calendar_snapshot('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,'[]')$$,'missing remote event reconciles');
select is((select sync_state from public.calendar_events where ical_uid='shared-event@example'),'conflict','remote deletion cannot silently discard local edit');
select is((select remote_conflict_ical from public.calendar_events where ical_uid='shared-event@example'),'','remote deletion is explicit conflict payload');
select lives_ok($$select public.release_calendar_sync('00000200-0000-4000-8000-000000000201',current_setting('test.calendar_token')::uuid,'Resolve conflicts')$$,'lease released after failure');
select is((select last_synced_at from public.calendar_connections),null::timestamptz,'failed sync does not claim success');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000202',true);
select lives_ok($$select public.disconnect_calendar('00000200-0000-4000-8000-000000000201')$$,'partner can disconnect the shared connection');
select is((select count(*) from public.calendar_connections),0::bigint,'disconnect removes encrypted credential record');
select is((select count(*) from public.calendar_events),1::bigint,'disconnect retains local calendar history');
select is((select sync_state from public.calendar_events),'local','disconnected events become local');
select is((select connection_id from public.calendar_events),null::uuid,'disconnected events release connection reference');
reset role;
select is_empty($$select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='calendar_connections'$$,'encrypted connections are never realtime published');
select * from finish();
rollback;
